<?php
declare(strict_types=1);
$dir=sys_get_temp_dir().'/hunta-tg-'.bin2hex(random_bytes(5));mkdir($dir,0700);mkdir($dir.'/photos',0700);
$config=['storage'=>$dir,'site_url'=>'https://example.test','telegram_token'=>'123456:'.str_repeat('a',35),'telegram_channel'=>'-100123'];
file_put_contents($dir.'/config.php','<?php return '.var_export($config,true).';');putenv('HUNTA_CONFIG='.$dir.'/config.php');
require dirname(__DIR__).'/app/bootstrap.php';$db->exec(file_get_contents(ROOT.'/database.sql'));
function tg_assert(bool $ok,string $label):void{if(!$ok)throw new RuntimeException('FAIL: '.$label);echo 'OK: '.$label."\n";}
function tg_fails(callable $f,string $label):void{try{$f();}catch(RuntimeException $e){echo 'OK: '.$label."\n";return;}throw new RuntimeException('FAIL: '.$label);}
function tg_post(string $slug,string $text):array{global $db;$db->prepare("INSERT INTO posts(slug,title,body,status,created_at,updated_at,published_at) VALUES(?,?,?,'published',?,?,?)")->execute([$slug,'Название',$text,now(),now(),now()]);return post((int)$db->lastInsertId());}
try{
    $p=tg_post('format',DAO_RICH_PREFIX.'<p>Начало <strong>🧸 жирный <em>курсив</em></strong></p><p>Пауза</p><blockquote>Слова <a href="/one">ссылка</a></blockquote>');
    $db->prepare('INSERT INTO post_categories VALUES(?,?)')->execute([$p['id'],category_by_slug('vinnie')['id']]);$p=post($p['id']);
    $doc=telegram_document($p);tg_assert(str_contains($doc['text'],"Дао Винни\n\nНазвание\n\nНачало")&&str_contains($doc['text'],"\n\nПауза")&&str_ends_with($doc['text'],'/?p=format'),'full story, line label, paragraph pauses and permalink');
    $selected=[];foreach($doc['entities'] as $e){$selected[$e['type']][]=mb_convert_encoding(substr(mb_convert_encoding($doc['text'],'UTF-16LE','UTF-8'),$e['offset']*2,$e['length']*2),'UTF-8','UTF-16LE');if($e['type']==='text_link')tg_assert($e['url']==='https://example.test/one','relative link made absolute');}
    tg_assert(in_array('🧸 жирный курсив',$selected['bold'],true)&&in_array('курсив',$selected['italic'],true)&&isset($selected['blockquote']),'UTF-16 formatting offsets after emoji');
    tg_assert(in_array('Дао Винни',$selected['bold'],true)&&in_array('Дао Винни',$selected['italic'],true),'series label is bold italic without changing the text');
    $gena=$p;$gena['category_slug']='gena';$genaDoc=telegram_document($gena);tg_assert(str_starts_with($genaDoc['text'],'Дао Гены')&&count(array_filter($genaDoc['entities'],fn($e)=>$e['offset']===0 && $e['length']===telegram_units('Дао Гены')))===2,'Gena series label has the same emphasis');
    $long=telegram_document($p+[]);$long['text']=str_repeat("🧸 длинная мысль\n\n",1000);$long['entities']=[['type'=>'italic','offset'=>0,'length'=>telegram_units($long['text'])]];$chunks=telegram_chunks($long);tg_assert(implode('',array_column($chunks,'text'))===$long['text'],'long text split loses no characters');foreach($chunks as $c)tg_assert(telegram_units($c['text'])<=3900 && $c['entities'][0]['length']===telegram_units($c['text']),'chunk entity clipped to valid UTF-16 bounds');
    $photo=str_repeat('a',32).'.png';file_put_contents($dir.'/photos/'.$photo,base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jN1cAAAAASUVORK5CYII='));
    $db->prepare('UPDATE posts SET cover=? WHERE id=?')->execute([$photo,$p['id']]);$p=post($p['id']);tg_assert(count(telegram_plan($p))===1 && telegram_plan($p)[0]['kind']==='photo','short story is full caption with image');
    $calls=[];$nextId=100;$mock=function($method,$payload)use(&$calls,&$nextId){$calls[]=[$method,$payload];return ['ok'=>true,'result'=>['message_id'=>$payload['message_id']??++$nextId]];};
    telegram_send($p['id'],$mock);telegram_send($p['id'],$mock);tg_assert(array_column($calls,0)===['sendPhoto','editMessageMedia'],'repeat updates photo instead of duplicating');tg_assert($calls[0][1]['photo'] instanceof CURLFile,'image uploaded directly, not link preview');
    $db->prepare('UPDATE posts SET body=? WHERE id=?')->execute([str_repeat("Мысль\n\n",1100),$p['id']]);$calls=[];telegram_send($p['id'],$mock);tg_assert($calls[0][0]==='editMessageMedia' && count($calls)>2,'long story has photo plus all text chunks');
    $db->prepare('UPDATE posts SET body=? WHERE id=?')->execute(['Коротко',$p['id']]);$calls=[];telegram_send($p['id'],$mock);tg_assert(in_array('deleteMessage',array_column($calls,0),true),'shorter update removes obsolete text parts');
    $p2=tg_post('partial',str_repeat('я',6000));$attempt=0;
    tg_fails(fn()=>telegram_send($p2['id'],function($method,$payload)use(&$attempt){if(++$attempt===2)throw new RuntimeException('timeout');return ['ok'=>true,'result'=>['message_id'=>501]];}),'partial timeout stops safely');
    tg_fails(fn()=>telegram_send($p2['id'],$mock),'unknown part blocks duplicate retry');telegram_resolve($p2['id'],502);$calls=[];telegram_send($p2['id'],$mock);tg_assert(array_column($calls,0)===['editMessageText','editMessageText'],'manual reconciliation edits both known parts');
    telegram_schedule_post($p['id'],date('Y-m-d\TH:i',time()+3600));$job=$db->query('SELECT * FROM telegram_schedule ORDER BY id DESC')->fetch();$frozen=json_decode($job['snapshot'],true);$db->prepare('UPDATE posts SET body=? WHERE id=?')->execute(['Новая версия',$p['id']]);$db->exec('UPDATE telegram_schedule SET due_at=0');$calls=[];tg_assert(telegram_run_due($mock)===1,'due schedule delivered');tg_assert($calls[0][1]['media']['caption']===telegram_text($frozen),'scheduled snapshot stays frozen');$calls=[];telegram_run_due($mock);tg_assert($calls===[],'completed task never repeated');
    telegram_schedule_post($p['id'],date('Y-m-d\TH:i',time()+3600));telegram_cancel_schedule($p['id']);$db->exec('UPDATE telegram_schedule SET due_at=0');tg_assert(telegram_run_due($mock)===0,'cancelled task never delivered');
    telegram_schedule_post($p['id'],date('Y-m-d\TH:i',time()+3600));$db->exec('UPDATE telegram_schedule SET due_at=0');$config['telegram_channel']='-100456';$calls=[];tg_assert(telegram_run_due($mock)===0 && $calls===[],'changed channel cannot redirect queued story');$config['telegram_channel']='-100123';
    telegram_schedule_post($p['id'],date('Y-m-d\TH:i',time()+3600));$db->exec('UPDATE telegram_schedule SET due_at=0');$db->prepare("UPDATE posts SET status='draft' WHERE id=?")->execute([$p['id']]);$calls=[];tg_assert(telegram_run_due($mock)===0 && $calls===[],'unpublished story never sent by scheduler');
    $readCalls=[];$readOnly=function($method,$payload)use(&$readCalls){$readCalls[]=$method;return ['ok'=>true,'result'=>match($method){'getMe'=>['id'=>5,'username'=>'dummy_bot'],'getChat'=>['id'=>-100789,'type'=>'channel','title'=>'Тестовый канал'],'getChatMember'=>['status'=>'administrator','can_post_messages'=>true,'can_edit_messages'=>true],default=>throw new RuntimeException('Unexpected publication')}];};
    telegram_save_connection(['telegram_channel'=>'@test_channel','telegram_token'=>$config['telegram_token']],$readOnly);tg_assert($readCalls===['getMe','getChat','getChatMember'] && $config['telegram_channel']==='-100789','connection verified read-only and pinned to channel ID');tg_assert((fileperms($dir.'/telegram-connection.php')&0777)===0600,'token file owner-only');
    $p3=tg_post('worker-failure','Полная история');telegram_schedule_post($p3['id'],date('Y-m-d\TH:i',time()+3600));$db->exec('UPDATE telegram_schedule SET due_at=0');$failCalls=0;
    telegram_run_due(function()use(&$failCalls){$failCalls++;throw new RuntimeException('timeout');});telegram_run_due($mock);tg_assert($failCalls===1,'scheduled timeout never automatically retried');
    $p4=tg_post('orphan','Ещё история');telegram_schedule_post($p4['id'],date('Y-m-d\TH:i',time()+3600));$db->exec("UPDATE telegram_schedule SET state='running' WHERE state='scheduled'");$calls=[];telegram_run_due($mock);tg_assert($calls===[] && !$db->query("SELECT 1 FROM telegram_schedule WHERE state='running'")->fetchColumn(),'dead worker task stops without resending');
    $code=telegram_document(['title'=>'Код','telegram_text'=>'','body'=>DAO_RICH_PREFIX.'<p><strong>До <code>echo 1;</code> после</strong></p>','slug'=>'code']);$ranges=[];
    foreach($code['entities'] as $e)if($e['type']==='code')$ranges[]=$e;
    foreach($code['entities'] as $e)if($e['type']==='bold')foreach($ranges as $r)tg_assert($e['offset']+$e['length']<=$r['offset'] || $e['offset']>=$r['offset']+$r['length'],'code entities do not overlap bold');
    $connectionBefore=file_get_contents($dir.'/telegram-connection.php');tg_fails(fn()=>telegram_save_connection(['telegram_channel'=>'@denied_channel'],fn($method,$payload)=>$method==='getChatMember'?['ok'=>true,'result'=>['status'=>'member']]:$readOnly($method,$payload)),'missing admin rights rejected');tg_assert(file_get_contents($dir.'/telegram-connection.php')===$connectionBefore,'failed check preserves previous connection');
    $db->exec(file_get_contents(ROOT.'/database.sql'));tg_assert(post($p['id'])['body']==='Новая версия','migration preserves existing stories');
}finally{$db=null;foreach(glob($dir.'/photos/*') as $f)unlink($f);rmdir($dir.'/photos');foreach(glob($dir.'/*') as $f)if(is_file($f))unlink($f);rmdir($dir);}
